 {World w;w.startLegacyMission(3);check(w.missionAllows(Kind::Knight)&&!w.missionAllows(Kind::Shipyard)&&w.missionResearchAllows(Research::Town2),"fourth mission introduces cavalry before navy");check(!w.missionRaidReady(),"fourth mission raids wait for preparation");w.gather(*w.get(4),find(w,Kind::Mine,-1));advance(w,240);check(!w.missionRaidReady()&&w.result==0&&w.get(w.archivist),"refuge and base survive unhurried preparation");check(w.research(1,Research::Town2),"fourth mission paid command II starts");advance(w,19);check(w.build(2,{850,1000},Kind::Stable),"fourth mission paid stable builds");int stable=w.entities.back().id;advance(w,25);check(w.train(stable,Kind::Knight),"first paid knight starts");advance(w,13);check(w.train(stable,Kind::Knight),"second paid knight starts");advance(w,13);check(w.build(3,{1180,920},Kind::GuardTower),"defensive tower builds at pass");advance(w,25);check(w.missionStage==1&&!w.missionRaidReady(),"completed preparation starts announced grace period");auto saved=snapshot(w);World copy;std::istringstream input(saved);check(copy.restore(input)&&snapshot(copy)==saved,"fourth mission timer refuge and unlocks survive save");check(w.missionObjective().find("Assalto tra")!=std::string::npos,"defense objective announces countdown");}

 {World w;w.startLegacyMission(3);w.gather(*w.get(4),find(w,Kind::Mine,-1));w.gather(*w.get(5),find(w,Kind::Mine,-1));check(w.research(1,Research::Town2),"active defense command research paid");advance(w,19);check(w.build(2,{850,1000},Kind::Stable),"active defense stable starts");int stable=w.entities.back().id;advance(w,25);check(w.train(stable,Kind::Knight),"active defense first knight");advance(w,13);check(w.train(stable,Kind::Knight),"active defense second knight");advance(w,13);check(w.build(3,{1180,920},Kind::GuardTower),"active defense tower starts");advance(w,25);for(auto& e:w.entities)if(e.hp>0&&e.team==0&&mobile(e.kind)&&e.kind!=Kind::Worker)w.move(e,{1350,800});advance(w,150);check(w.result==0&&w.missionStage==2&&w.get(w.archivist),"paid enemy army and live defense remain beatable with starter mixed army");std::vector<int> army;for(const auto& e:w.entities)if(e.hp>0&&e.team==0&&mobile(e.kind)&&e.kind!=Kind::Worker)army.push_back(e.id);for(int id:army)w.attack(*w.get(id),w.missionGuards.front());advance(w,90);check(w.result==1,"fourth mission won through live combat and enemy economy");}
 {World w;w.startLegacyMission(3);w.missionStage=1;w.wave=0;w.raidsEnabled=false;for(auto& e:w.entities)if(e.team==1)e.hp=0;w.move(*w.get(find(w,Kind::Soldier)),{1350,800});advance(w,25);check(w.secureTime>0&&w.secureTime<90,"defense time requires real army presence");auto saved=snapshot(w);World copy;std::istringstream input(saved);check(copy.restore(input),"defense in progress loads");advance(w,100);advance(copy,100);check(w.result==1&&copy.result==1&&snapshot(w)==snapshot(copy),"defense and destroyed barracks complete identically after load");}
