 for(bool active:{false,true}){World w;w.startLegacyMission(4);w.raidsEnabled=active;w.gather(*w.get(4),find(w,Kind::Mine,-1));check(w.water({1500,1400})&&!w.water({2020,1480}),"fifth mission has sea and a real island");auto soldier=find(w,Kind::Soldier);check(!w.path(*w.get(soldier),{2020,1480},100),"island cannot be reached by walking");check(w.missionAllows(Kind::Transport)&&!w.missionAllows(Kind::Battleship)&&!w.missionResearchAllows(Research::Town3),"coastal mission unlocks first navy but retains advanced locks");check(w.build(2,{700,1120},Kind::Shipyard),"coastal port built by worker");int port=w.entities.back().id;advance(w,25);check(w.train(port,Kind::Tanker),"paid tanker starts");advance(w,11);int tanker=find(w,Kind::Tanker);check(tanker>0&&w.water(w.get(tanker)->pos),"tanker spawns on sea");check(w.build(tanker,{900,1320},Kind::OilRig),"tanker builds paid platform on real deposit");int rig=w.entities.back().id;advance(w,25);w.gather(*w.get(tanker),rig);advance(w,100);check(w.oil>=60&&w.missionStage==1,"finite oil extracted and delivered advances mission");check(w.train(port,Kind::Destroyer),"escort frigate consumes delivered oil");advance(w,15);for(auto& e:w.entities)if(e.hp>0&&e.team==0&&e.kind==Kind::Destroyer)w.move(e,{1000,1280});check(w.train(port,Kind::Destroyer),"second paid escort starts with gathered gold");advance(w,15);for(auto& e:w.entities)if(e.hp>0&&e.team==0&&e.kind==Kind::Destroyer)w.move(e,{1000,1280});check(w.train(port,Kind::Transport),"transport consumes delivered oil");advance(w,13);int ship=find(w,Kind::Transport);check(ship>0&&w.missionStage==2,"transport opens island objective");w.move(*w.get(ship),{780,1240});advance(w,10);std::vector<int> troops;for(auto& e:w.entities)if(e.team==0&&(e.kind==Kind::Soldier||e.kind==Kind::Archer)){troops.push_back(e.id);w.board(e,ship);}advance(w,30);int boarded=0;for(int id:troops)if(w.get(id)&&w.get(id)->carrier==ship)++boarded;check(boarded==5,"five real troops board coastal transport");auto saved=snapshot(w);World copy;std::istringstream input(saved);check(copy.restore(input)&&snapshot(copy)==saved,"embarked army ship and oil economy survive save");for(auto& e:w.entities)if(e.hp>0&&e.team==0&&e.kind==Kind::Destroyer)w.move(e,{1700,1320});w.move(*w.get(ship),{1770,1460});for(int second=0;second<22;++second){int hostile=find(w,Kind::Destroyer,1);if(hostile>0)for(auto& e:w.entities)if(e.hp>0&&e.team==0&&e.kind==Kind::Destroyer)w.attack(e,hostile);advance(w,1);}check(w.unload(ship,{1860,1480}),"troops disembark on island rather than fixed mainland shore");for(int id:troops)check(w.get(id)&&w.get(id)->carrier<0&&!w.water(w.get(id)->pos),"disembarked troop stands on island land");for(auto& enemy:w.entities)if(enemy.team==1&&mobile(enemy.kind)&&enemy.pos.y>1400){int id=enemy.id;for(int troop:troops)if(w.get(troop))w.attack(*w.get(troop),id);advance(w,25);}for(int troop:troops)if(w.get(troop))w.move(*w.get(troop),{2010,1460});advance(w,40);check(w.result==1,"actual oil transport landing combat and occupation win fifth mission");}
