 {World w;w.startLegacyMission(4);w.raidsEnabled=false;check(w.cols==144&&w.rows==90&&w.width()==5760&&w.height()==3600,"fifth mission has its progressive map dimensions");auto unit=w.get(find(w,Kind::Soldier));w.move(*unit,{3000,900});advance(w,45);check(unit->pos.x>2600,"units can explore beyond the old map boundary");w.refreshVision();check(w.exploredAt(unit->pos),"expanded territory is revealed by units");auto saved=snapshot(w);World copy;std::istringstream input(saved);check(copy.restore(input)&&snapshot(copy)==saved&&copy.cols==144,"expanded map exploration and routes survive save");}
